const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometries for Antakya and Altınözü
  const antakya = ee.Geometry.Point([36.1610, 36.2082]); // Antakya coordinates
  const altınozu = ee.Geometry.Point([36.2333, 36.0667]); // Altınözü coordinates

  // VIIRS Nighttime Lights collection
  const viirs = ee.ImageCollection('VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .select('avg_rad');

  // Get February 2023 data
  const feb2023 = viirs
    .filter(ee.Filter.date('2023-02-01', '2023-03-01'))
    .first();

  // Get April 2023 data
  const apr2023 = viirs
    .filter(ee.Filter.date('2023-04-01', '2023-05-01'))
    .first();

  // Check if images exist
  const febInfo = feb2023.getInfo();
  const aprInfo = apr2023.getInfo();

  if (!febInfo || !aprInfo) {
    console.log("No data found for one or both time periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean nighttime light for Antakya
  const antakyaFeb = feb2023.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: antakya,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const antakyaApr = apr2023.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: antakya,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  // Calculate mean nighttime light for Altınözü
  const altinozuFeb = feb2023.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: altınozu,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const altinozuApr = apr2023.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: altınozu,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  // Check for null or invalid values
  if (antakyaFeb === null || antakyaApr === null || 
      altinozuFeb === null || altinozuApr === null) {
    console.log("Calculation failed - null values returned.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate increases
  const antakyaIncrease = antakyaApr - antakyaFeb;
  const altinozuIncrease = altinozuApr - altinozuFeb;

  // Print evidence
  console.log(`Antakya Feb 2023: ${antakyaFeb.toFixed(3)} nW/cm²/sr`);
  console.log(`Antakya Apr 2023: ${antakyaApr.toFixed(3)} nW/cm²/sr`);
  console.log(`Antakya Increase: ${antakyaIncrease.toFixed(3)}`);
  console.log(`Altınözü Feb 2023: ${altinozuFeb.toFixed(3)} nW/cm²/sr`);
  console.log(`Altınözü Apr 2023: ${altinozuApr.toFixed(3)} nW/cm²/sr`);
  console.log(`Altınözü Increase: ${altinozuIncrease.toFixed(3)}`);

  // Compare increases
  if (antakyaIncrease > altinozuIncrease) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
